def without_failed_peer_diagnostic(source):
    for reviewed, original in REPLACEMENTS:
        if source.count(reviewed) != 1:
            raise ValueError('Changed or duplicate failed peer diagnostic block')
        source = source.replace(reviewed, original, 1)
    return source
